// runExplainAutoTestRepo seeds a git repo and returns the initial commit's hash.
func runExplainAutoTestRepo(t *testing.T) (repo *git.Repository, initialCommit plumbing.Hash) {
	t.Helper()
	tmpDir := t.TempDir()
